  function mrz(char){const name=clean(char.englishName||'').toUpperCase().replace(/[^A-Z0-9]+/g,'<')||'STUDENT';return `PHS<<${name}<<${studentNo(char).replace(/[^0-9A-Z]/gi,'')}`.padEnd(34,'<').slice(0,34);}
