      const docs=documents.filter(d=>d.bookId===book.id&&!d.hideFromDocuments),hasVn=docs.some(isVn);
      return `<section class="ps-book-hero" style="--c:${esc(book.iconColor||'#b8935a')}"><span class="ps-book-spine"><i class="fa-solid fa-book"></i></span><div><span class="ps-kicker">ARCHIVE · BOOK</span><h1>${esc(book.title)}</h1><p>${esc(book.description||'')}</p><div class="ps-tags">${(book.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${hasVn?`<div class="ps-hero-actions">${btn('<i class="fa-solid fa-play"></i> 從第一章播放','book-play',`data-id="${esc(book.id)}"`,'ps-btn ps-btn-primary')}</div>`:''}</div></section>
      <section class="ps-card">${head('A','Chapters',`章節 · ${docs.length}`)}${docs.length?docs.map(docRow).join(''):'<p class="ps-muted">這本書還沒有章節。</p>'}</section>`;
