  function clubCard(club,i=0){const list=clubMembers(club),officers=(club.officers||[]).map(o=>person(o.charId)).filter(Boolean),advisors=list.filter(c=>roleOf(c)==='teacher');return `<div class="ps-qwrap"><button type="button" class="ps-club" data-go="club" data-id="${esc(club.id)}" style="--c:${esc(club.color)};--i:${i}"><span class="ps-club-banner ps-style-${esc(club.imageStyle||'original')}">${club.image?img(club.image,'ps-styled'):''}<span class="ps-club-badge">${icon(club.icon)}</span></span><span class="ps-club-body"><small>${club.kind==='org'?'ORGANIZATION':'CLUB'}${club.en?` · ${esc(club.en)}`:''}</small><b>${esc(club.name)}</b>${club.aliases?.length?`<em>${esc(club.aliases.join('／'))}</em>`:''}<span class="ps-club-meta"><span><i class="fa-solid fa-users"></i> ${list.filter(c=>roleOf(c)==='student').length}</span>${advisors.length?`<span><i class="fa-solid fa-chalkboard-user"></i> ${esc(advisors.map(nameOf).join('、'))}</span>`:''}${officers.length?`<span><i class="fa-solid fa-crown"></i> ${esc(officers.map(nameOf).join('、'))}</span>`:''}</span><span class="ps-av-stack ps-av-stack-sm">${list.slice(0,7).map(c=>avatar(c)).join('')}${list.length>7?`<span class="ps-more">+${list.length-7}</span>`:''}</span></span></button>${quick([['club-edit',club.id,'fa-pen','編輯'],['club-delete',club.id,'fa-trash','刪除',true]])}</div>`;}
