  /* AI report: reads the linked books' chapters (text and VN scripts) and drafts the report */
  async function aiReport(evId){const a=app(),ev=a.events.find(e=>e.id===evId);if(!ev)return;
    if(typeof requestDeepSeek!=='function'||!deepseekSettings?.apiKey){toast('請先在設定表的 AI 設定填入 DeepSeek API Key');return;}
    const list=eventBooks(ev);if(!list.length&&!docsById(ev.docIds).length){toast('請先在活動中關聯書籍或文檔');return;}
    const chapters=[...list.flatMap(b=>documents.filter(d=>d.bookId===b.id).map(d=>({book:b.title,doc:d}))),...docsById(ev.docIds).filter(d=>!list.some(b=>b.id===d.bookId)).map(d=>({book:'',doc:d}))];
    const limit=60000;let used=0;const parts=[];for(const {book,doc} of chapters){const text=String(doc.content||doc.visualNovel?.scriptText||'').trim();if(!text)continue;const room=limit-used;if(room<500)break;const piece=text.slice(0,room);used+=piece.length;parts.push(`【${book?book+'｜':''}${doc.title||'未命名章節'}】\n${piece}`);}
    if(!parts.length){toast('關聯的書籍沒有可閱讀的內文');return;}
    const people=participants(ev).map(c=>`${nameOf(c)}（${roleOf(c)==='teacher'?'教師':val(c,'grade')||'學生'}${val(c,'post')?'，'+val(c,'post'):''}）`).join('、');
    const context=[`學校：${a.meta.name}（${a.meta.en}）`,`活動：${ev.title}`,`日期：${fmtDate(ev.date)}${ev.endDate&&ev.endDate!==ev.date?'–'+fmtDate(ev.endDate):''}`,`地點：${facility(ev.location)?.name||ev.locationText||'未定'}`,`類型：${(EVENT_KINDS[ev.kind]||EVENT_KINDS.standard).name}`,people?`參加者：${people}`:'',linkedParo(ev)?`活動設定：${oneLine(linkedParo(ev).description)}`:'',ev.kind==='teams'&&ev.teams?.length?`隊伍與比分：${ev.teams.map(t=>`${t.name} ${teamScore(ev,t)} 分`).join('、')}`:'',ev.summary?`現有摘要：${ev.summary}`:''].filter(Boolean).join('\n');
    openLayer(`<div class="ps-ai-wait"><span class="ps-ai-orb"></span><b>AI 正在閱讀 ${parts.length} 個章節…</b><small>約 ${used.toLocaleString()} 字，請稍候</small></div>`,{cls:'is-ai'});
    try{const data=await requestDeepSeek({model:'deepseek-v4-flash',temperature:.7,messages:[{role:'system',content:'你是校園刊物編輯，用繁體中文撰寫活動報告。只根據提供的章節內容與活動資料，不捏造情節；人物名稱照原文。'},{role:'user',content:`請閱讀以下章節，為這個校園活動撰寫一篇活動報告。\n\n輸出格式：\n第一行以「摘要：」開頭，寫一句 40 字內的摘要。\n之後是報告正文，約 600～1200 字，段落之間空一行；可用「# 小標題」、「> 引言（引用角色台詞）」、**粗體**。不要輸出其他說明。\n\n【活動資料】\n${context}\n\n【章節內容】\n${parts.join('\n\n')}`}]},180000);
      const text=String(data.choices[0].message.content||'').trim(),m=text.match(/^摘要[:：]\s*(.+)\n+/),summary=m?m[1].trim():'',body=m?text.slice(m[0].length).trim():text;
      openLayer(`<form class="ps-form" data-ps-form><header class="ps-sheet-head"><div><small>AI DRAFT</small><h3>AI 活動報告草稿</h3></div><button type="button" class="ps-icon-btn" data-act="layer-close"><i class="fa-solid fa-xmark"></i></button></header><div class="ps-sheet-body">${field('摘要',input('summary',summary))}${field('報告正文（可直接修改）',textarea('body',body,14))}<label class="ps-check"><input type="radio" name="how" value="replace" ${ev.body?'':'checked'}><span>取代目前的報告</span></label><label class="ps-check"><input type="radio" name="how" value="append" ${ev.body?'checked':''}><span>加在目前報告的後面</span></label><p class="ps-muted">讀取了 ${parts.length} 個章節（約 ${used.toLocaleString()} 字）${used>=limit-500?'，內容過長已截斷':''}。</p></div><footer class="ps-sheet-foot"><span></span><button type="button" class="ps-btn ps-btn-ghost" data-act="layer-close">捨棄</button><button type="submit" class="ps-btn ps-btn-primary">套用到活動</button></footer></form>`,{cls:'is-wide',onSubmit:data=>{ev.body=data.how==='append'&&ev.body?`${ev.body}\n\n${data.body}`:data.body;if(data.summary.trim()&&(!ev.summary||data.how==='replace'))ev.summary=data.summary.trim();save();render();toast('已套用 AI 報告');return true;}});
    }catch(error){closeLayer(true);toast(error.message||'AI 生成失敗');console.warn(error);}}
  function docChoices(selected){const set=new Set(selected);const byBook=new Map();for(const doc of documents){if(doc.hideFromDocuments)continue;const key=doc.bookId||'';if(!byBook.has(key))byBook.set(key,[]);byBook.get(key).push(doc);}const bookTitle=id=>(typeof books!=='undefined'?books:[]).find(b=>b.id===id)?.title||'未分類';return [...byBook].map(([bid,docs])=>`<h5 class="ps-pick-group">${esc(bookTitle(bid))}</h5>${docs.map(d=>{const vn=d.format==='visualNovel'||!!d.visualNovel?.scriptText;return `<label class="ps-pick${set.has(d.id)?' is-on':''}"><input type="checkbox" name="docs" value="${esc(d.id)}" ${set.has(d.id)?'checked':''}><i class="fa-solid ${vn?'fa-clapperboard':'fa-file-lines'}"></i><span><b>${esc(d.title||'未命名')}</b><small>${vn?'視覺小說':'文檔'} · ${esc(bookTitle(bid))}</small></span></label>`;}).join('')}`).join('')||'<p class="ps-muted">設定表中還沒有文檔。</p>';}
  function addArchive(){const a=app(),have=new Set(a.archive.map(x=>`${x.kind}:${x.refId}`));const bookRows=(typeof books!=='undefined'?books:[]).map(b=>`<label class="ps-pick"><input type="checkbox" name="pick" value="book:${esc(b.id)}" ${have.has(`book:${b.id}`)?'checked disabled':''}><i class="fa-solid fa-book" style="color:${esc(b.iconColor||'#b8935a')}"></i><span><b>${esc(b.title)}</b><small>書籍 · ${documents.filter(d=>d.bookId===b.id).length} 章</small></span></label>`).join('');
    const docRows=documents.map(d=>{const vn=d.format==='visualNovel'||!!d.visualNovel?.scriptText;return `<label class="ps-pick"><input type="checkbox" name="pick" value="doc:${esc(d.id)}" ${have.has(`doc:${d.id}`)?'checked disabled':''}><i class="fa-solid ${vn?'fa-clapperboard':'fa-file-lines'}"></i><span><b>${esc(d.title||'未命名')}</b><small>${vn?'視覺小說':'章節'} · ${esc((typeof books!=='undefined'?books:[]).find(b=>b.id===d.bookId)?.title||'未分類')}</small></span></label>`;}).join('');
    dialog('關聯小說／視覺小說',`<div class="ps-grid-2">${field('分類（選填）',input('category','','placeholder="例如：校園日常、學生會事件簿"'))}${field('附註（選填）',input('note',''))}</div><label class="ps-check"><input type="checkbox" name="hideLib" value="1"><span>加入後在同人文庫中隱藏</span></label><label class="ps-field-inline"><i class="fa-solid fa-magnifying-glass"></i><input type="search" data-filter-q placeholder="搜尋書名或章節"></label><div class="ps-pick-list" data-filter-list><h5 class="ps-pick-group">書籍</h5>${bookRows||'<p class="ps-muted">沒有書籍。</p>'}<h5 class="ps-pick-group">章節與視覺小說</h5>${docRows||'<p class="ps-muted">沒有文檔。</p>'}</div>`,{en:'ARCHIVE',wide:true,submit:'加入檔案庫',onSubmit:data=>{for(const value of data.pick||[]){const [kind,refId]=value.split(':');if(have.has(value))continue;a.archive.push({id:uid('arc'),kind,refId,category:data.category.trim(),note:data.note.trim(),nodeId:'',parallel:false});if((data.hideLib||[]).length){const ref=kind==='book'?(typeof books!=='undefined'?books:[]).find(b=>b.id===refId):documents.find(d=>d.id===refId);if(ref)ref.hideFromDocuments=true;}}try{renderDocumentsModule();}catch{}save();render();return true;}});
}
  function editArchive(id){const a=app(),entry=a.archive.find(x=>x.id===id);if(!entry)return;const ref=archiveRef(entry),nodes=a.archiveTimeline.nodes;
    dialog('檔案設定與附註',`${field('分類',input('category',entry.category))}${field('附註',textarea('note',entry.note,4),'顯示在檔案庫卡片上，不會修改原本的書籍或章節。')}<div class="ps-grid-2">${field('時間線節點',select('nodeId',[['','—（不指定）'],...nodes.map(n=>[n.id,n.title])],entry.nodeId||''))}<label class="ps-check ps-check-end"><input type="checkbox" name="parallel" value="1" ${entry.parallel?'checked':''}><span>與時間線上一份檔案並列</span></label></div>${ref?`<label class="ps-check"><input type="checkbox" name="hideLib" value="1" ${ref.hideFromDocuments?'checked':''}><span>在同人文庫中隱藏這${entry.kind==='book'?'本書':'篇章節'}（仍可在校園檔案庫開啟）</span></label>`:''}`,{en:'ARCHIVE',onSubmit:data=>{entry.category=data.category.trim();entry.note=data.note.trim();entry.nodeId=data.nodeId||'';entry.parallel=(data.parallel||[]).length>0;if(ref){ref.hideFromDocuments=(data.hideLib||[]).length>0;try{renderDocumentsModule();}catch{}}save();render();return true;}});}
